#include <stdio.h>
#include <string.h>

int main(void)
{
    FILE *out = fopen("scores.txt", "w");
    if (out == NULL) {
        perror("scores.txt");
        return 1;
    }
    char line[256];
    long total = 0;
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        char name[64];
        long score = 0;
        char extra = 0;
        if (sscanf(line, "%63s %ld %c", name, &score, &extra) != 2) {
            if (line[0] != '\0') fprintf(stderr, "Skipped: %s\n", line);
            continue;
        }
        fprintf(out, "%s,%ld\n", name, score);
        total += score;
    }
    fclose(out);

    out = fopen("scores.txt", "a");
    if (out == NULL) {
        perror("scores.txt");
        return 1;
    }
    fprintf(out, "total,%ld\n", total);
    fclose(out);

    FILE *in = fopen("scores.txt", "r");
    if (in == NULL) {
        perror("scores.txt");
        return 1;
    }
    char best_name[64] = "";
    long best = 0;
    int have_best = 0;
    int number = 0;
    while (fgets(line, sizeof line, in) != NULL) {
        number++;
        printf("%d: %s", number, line);
        char name[64];
        long score = 0;
        if (sscanf(line, "%63[^,],%ld", name, &score) == 2 && strcmp(name, "total") != 0) {
            if (!have_best || score > best) {
                best = score;
                snprintf(best_name, sizeof best_name, "%s", name);
                have_best = 1;
            }
        }
    }
    fclose(in);
    if (have_best) printf("Best: %s (%ld)\n", best_name, best);
    else printf("Best: none\n");
    return 0;
}
